DO $$
DECLARE b uuid:=gen_random_uuid(); foreign_b uuid:=gen_random_uuid(); a uuid:=gen_random_uuid();
 manager uuid:=gen_random_uuid(); resident uuid:=gen_random_uuid(); stranger uuid:=gen_random_uuid();
 booking uuid:=gen_random_uuid(); ticket uuid:=gen_random_uuid(); request uuid:=gen_random_uuid(); expense_request uuid:=gen_random_uuid(); r jsonb; entry uuid; charge uuid; rejected boolean;
BEGIN
 INSERT INTO public.buildings(id,name,balance) VALUES(b,'اختبار الإصلاحات',100),(foreign_b,'عمارة أخرى',0);
 INSERT INTO public.apartments(id,building_id,unit_number,monthly_fee,overdue_months) VALUES(a,b,'1',1000,3);
 INSERT INTO app_auth.users(id,email) VALUES(manager,manager||'@example.invalid'),(resident,resident||'@example.invalid'),(stranger,stranger||'@example.invalid');
 UPDATE public.profiles SET building_id=b,role='building_admin',approved=true WHERE id=manager;
 UPDATE public.profiles SET building_id=b,apartment_id=a,role='tenant',approved=true WHERE id=resident;
 UPDATE public.profiles SET building_id=foreign_b,role='building_admin',approved=true WHERE id=stranger;
 INSERT INTO private.auth_identity_map VALUES(manager::text,manager),(resident::text,resident),(stranger::text,stranger);
 INSERT INTO public.facility_bookings(id,building_id,apartment_id,facility,unit_number,resident_name,booking_date,time_slot,status,created_by) VALUES(booking,b,a,'الروف','1','ساكن',current_date,'5-7','قيد المراجعة',resident);
 INSERT INTO public.maintenance_tickets(id,building_id,apartment_id,unit_number,resident_name,category,title,description,status,urgency,created_by) VALUES(ticket,b,a,'1','ساكن','كهرباء','اختبار الصيانة','تفاصيل','جديد','عادي',resident);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',manager)::text,true);
 SET LOCAL ROLE authenticated;
 r:=public.mutate_financial_entry('payment','create',b,NULL,jsonb_build_object('apartmentId',a,'amount',3000,'date',current_date,'month','نوفمبر ٢٠٢٦','method','نقدي'),request);
 entry:=(r->'entry'->>'id')::uuid;
 IF (r->>'balance')::numeric<>3100 OR (r->'apartment'->>'overdue_months')::integer<>3 OR (r->'apartment'->>'credit_balance')::numeric<>0 THEN RAISE EXCEPTION 'Arrears or cash incorrect: %',r; END IF;
 r:=public.mutate_financial_entry('payment','create',b,NULL,jsonb_build_object('apartmentId',a,'amount',3000,'date',current_date,'month','نوفمبر ٢٠٢٦','method','نقدي'),request);
 IF (SELECT count(*) FROM public.payments WHERE building_id=b)<>1 OR (r->>'balance')::numeric<>3100 THEN RAISE EXCEPTION 'Retry duplicated cash'; END IF;
 rejected:=false;
 BEGIN PERFORM public.mutate_financial_entry('payment','create',b,NULL,jsonb_build_object('apartmentId',a,'amount',4000,'date',current_date,'month','نوفمبر ٢٠٢٦','method','نقدي'),request); EXCEPTION WHEN others THEN rejected:=true; END;
 IF NOT rejected THEN RAISE EXCEPTION 'Request ID reused with changed payload'; END IF;
 r:=public.mutate_financial_entry('payment','update',b,entry,jsonb_build_object('amount',2000,'date',current_date,'month','نوفمبر ٢٠٢٦','method','نقدي'),gen_random_uuid());
 IF (r->>'balance')::numeric<>2100 OR (r->'apartment'->>'payment_status')<>'pending' THEN RAISE EXCEPTION 'Update not atomic'; END IF;
 PERFORM public.mutate_financial_entry('payment','delete',b,entry,'{}',gen_random_uuid());
 r:=public.mutate_financial_entry('expense','create',b,NULL,jsonb_build_object('title','مصروف اختبار','category','أخرى','amount',150,'date',current_date),expense_request);
 entry:=(r->'entry'->>'id')::uuid;
 IF (r->>'balance')::numeric<>-50 THEN RAISE EXCEPTION 'Deficit was concealed'; END IF;
 r:=public.mutate_financial_entry('expense','delete',b,entry,'{}',gen_random_uuid());
 IF (r->>'balance')::numeric<>100 THEN RAISE EXCEPTION 'Reversal did not restore exact balance'; END IF;
 IF (SELECT count(*) FROM public.financial_audit_log WHERE building_id=b)<>5 THEN RAISE EXCEPTION 'Missing audit entries'; END IF;
 rejected:=false;
 BEGIN DELETE FROM public.financial_audit_log WHERE building_id=b; EXCEPTION WHEN insufficient_privilege THEN rejected:=true; END;
 IF NOT rejected THEN RAISE EXCEPTION 'Manager can delete audit'; END IF;
 r:=public.update_service_request('ticket',ticket,b,'قيد التنفيذ','الفني في الطريق');
 IF r->>'status'<>'قيد التنفيذ' OR r->>'manager_note'<>'الفني في الطريق' THEN RAISE EXCEPTION 'Ticket progression failed'; END IF;
 PERFORM public.update_service_request('ticket',ticket,b,'مكتمل','تم الإصلاح');
 r:=public.update_service_request('booking',booking,b,'مؤكد','موعدك مؤكد');
 IF r->>'status'<>'مؤكد' THEN RAISE EXCEPTION 'Booking confirmation failed'; END IF;
 -- Allocation guards and overpayment rejection still apply to exceptional receipts.
 r:=public.create_exceptional_collection(b,'اختبار مصعد','','total',500,NULL,ARRAY[a],false);
 SELECT id INTO charge FROM public.payments WHERE building_id=b AND is_assessment;
 r:=public.mutate_financial_entry('payment','create',b,NULL,jsonb_build_object('apartmentId',a,'exceptionalChargeId',charge,'amount',200,'date',current_date,'month','نوفمبر ٢٠٢٦','method','نقدي'),gen_random_uuid());
 IF (r->>'balance')::numeric<>300 THEN RAISE EXCEPTION 'Exceptional cash counted twice'; END IF;
 rejected:=false;
 BEGIN PERFORM public.mutate_financial_entry('payment','create',b,NULL,jsonb_build_object('apartmentId',a,'exceptionalChargeId',charge,'amount',400,'date',current_date,'month','نوفمبر ٢٠٢٦','method','نقدي'),gen_random_uuid()); EXCEPTION WHEN others THEN rejected:=true; END;
 IF NOT rejected OR (SELECT balance FROM public.buildings WHERE id=b)<>300 THEN RAISE EXCEPTION 'Overpayment changed cash'; END IF;
 RESET ROLE;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',resident)::text,true);
 SET LOCAL ROLE authenticated;
 IF EXISTS(SELECT FROM public.financial_audit_log WHERE building_id=b) THEN RAISE EXCEPTION 'Resident sees audit'; END IF;
 IF (SELECT manager_note FROM public.maintenance_tickets WHERE id=ticket)<>'تم الإصلاح' OR (SELECT status FROM public.facility_bookings WHERE id=booking)<>'مؤكد' THEN RAISE EXCEPTION 'Resident cannot see request outcome'; END IF;
 rejected:=false;
 BEGIN PERFORM public.update_service_request('booking',booking,b,'مؤكد','forged'); EXCEPTION WHEN insufficient_privilege THEN rejected:=true; END;
 IF NOT rejected THEN RAISE EXCEPTION 'Resident can confirm bookings'; END IF;
 rejected:=false;
 BEGIN PERFORM public.mutate_financial_entry('expense','delete',b,entry,'{}',gen_random_uuid()); EXCEPTION WHEN insufficient_privilege THEN rejected:=true; END;
 IF NOT rejected THEN RAISE EXCEPTION 'Resident financial write permitted'; END IF;
 RESET ROLE;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',stranger)::text,true);
 SET LOCAL ROLE authenticated;
 rejected:=false;
 BEGIN PERFORM public.mutate_financial_entry('payment','delete',b,entry,'{}',gen_random_uuid()); EXCEPTION WHEN insufficient_privilege THEN rejected:=true; END;
 IF NOT rejected THEN RAISE EXCEPTION 'Foreign manager write permitted'; END IF;
 IF EXISTS(SELECT FROM public.financial_audit_log WHERE building_id=b) THEN RAISE EXCEPTION 'Foreign manager sees audit'; END IF;
 RESET ROLE;
END $$;
